import random

GROUP = "number_theory"
SKILL = "induction"


def find_max_divisors(target, min_divisor_sum, max_divisor_sum):
    if target == 0:
        return 0

    if target < min_divisor_sum:
        return -1

    max_count = 0

    for divisor_sum in range(min_divisor_sum, max_divisor_sum + 1):
        if divisor_sum <= target:
            remaining_target = target - divisor_sum
            count = find_max_divisors(remaining_target, min_divisor_sum, divisor_sum - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_divisor_sum = rng.randint(5, 15)
    max_divisor_sum = rng.randint(25, 40)
    target_value = rng.randint(20, 50)

    answer = find_max_divisors(target_value, min_divisor_sum, max_divisor_sum)

    check = -1
    for divisor_sum in range(min_divisor_sum, max_divisor_sum + 1):
        if divisor_sum <= target_value:
            remaining_target = target_value - divisor_sum
            count = find_max_divisors(remaining_target, min_divisor_sum, divisor_sum - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider the divisors of a set of integers, where the sum of any subset of divisors ranges from {min_divisor_sum} to {max_divisor_sum} (inclusive). "
        f"What is the maximum number of distinct divisors that can be selected such that no subset sum exceeds the target sum {target_value} and all subset sums sum to exactly {target_value}? State only the integer."
    )
    return problem, str(answer)

import random

