def count_subsets(n, k):
    subsets = [0] * (k + 1)
    subsets[0] = 1

    for i in range(1, n + 1):
        for j in range(min(i, k), 0, -1):
            subsets[j] += subsets[j - 1]

    return subsets[k]

def generate(seed):
    rng = random.Random(seed)

    n = rng.randint(5, 15)
    k = rng.randint(2, n - 1)

    # Find the threshold k for which the subset can be formed
    for i in range(2, k + 1):
        if count_subsets(n, i) > 0:
            threshold_k = i
            break

    # Independent route: Iterate from the minimum k to find the smallest k that can form a valid subset.
    check_k = 2
    while True:
        if count_subsets(n, check_k) > 0:
            break
        check_k += 1

    assert threshold_k == check_k, f"threshold_k={threshold_k} check_k={check_k}"

    problem = (
        f"Determine the smallest size of subsets to be chosen from a set of {n} elements such that a subset of {threshold_k} elements can be formed where each element is unique and all elements sum to exactly {threshold_k}. State only the integer."
    )
    return problem, str(threshold_k)

