def count_terms(degree, min_degree, max_degree):
    terms = [0] * (degree + 1)
    terms[0] = 1

    for k in range(min_degree, max_degree + 1):
        for i in range(degree, k - 1, -1):
            terms[i] += terms[i - k]

    return terms[degree]

def generate(seed):
    rng = random.Random(seed)

    min_degree = rng.randint(2, 5)
    max_degree = rng.randint(10, 20)
    threshold_degree = 0

    # Find the threshold degree of terms
    for i in range(min_degree, max_degree + 1):
        if count_terms(i, min_degree, i) > 0:
            threshold_degree = i
            break

    # Independent route: iterate from the minimum degree to find the smallest degree that can form a valid polynomial combination.
    for i in range(min_degree, max_degree + 1):
        if count_terms(i, min_degree, i) > 0:
            check_threshold_degree = i
            break

    assert threshold_degree == check_threshold_degree, f"threshold_degree={threshold_degree} check_threshold_degree={check_threshold_degree}"

    problem = (
        f"Determine the smallest degree of polynomial terms from {min_degree} to {max_degree} (inclusive) such that a set of {threshold_degree} terms can be formed with each term between {min_degree} and {threshold_degree} (inclusive) where all terms sum to exactly {threshold_degree}. State only the integer."
    )
    return problem, str(threshold_degree)

